#include <iostream>
#include <vector>
#include <queue>
using namespace std;
int main() {
    int n,e; cin >> n >> e;
    vector<vector<int>> adj(n);
    vector<int> indegree(n, 0);
    for(int i=0; i<e; i++) { int u,v; cin>>u>>v; adj[u].push_back(v); indegree[v]++; }
    // Kahn's with priority_queue for lex smallest
    return 0;
}

